const input = $input.first()?.json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const msg = body.message || body.edited_message || {};
const chat = body.chat || msg.chat || {};
const rawText = String(body.text || body.command || body.prompt || msg.text || '').trim();
const chatId = String(body.chat_id || chat.id || '').trim();
const taskIdRaw = String(body.task_id || '').trim();
let action = 'run';
let prompt = rawText;
let task_id = taskIdRaw;
let executor = String(body.executor || '').trim().toLowerCase() === 'codex' ? 'codex' : 'dry_run';
if (/^\/killall\b/i.test(rawText) || String(body.action || '').toLowerCase() === 'killall') {
  action = 'killall';
  prompt = rawText;
} else if (/^\/status\b/i.test(rawText) || String(body.action || '').toLowerCase() === 'status') {
  action = 'status';
  task_id = taskIdRaw || rawText.replace(/^\/status\s*/i, '').trim();
} else if (/^\/codex\b/i.test(rawText)) {
  action = 'run';
  executor = 'codex';
  prompt = rawText.replace(/^\/codex\s*/i, '').trim() || 'Return TAC_CODEX_SMOKE_OK';
} else if (/^\/run\b/i.test(rawText)) {
  action = 'run';
  prompt = rawText.replace(/^\/run\s*/i, '').trim() || 'Phase 3 smoke run';
}
const endpoint = action === 'killall' ? 'killall' : action === 'status' ? 'status' : 'run';
const runner_url = `http://172.17.0.1:8765/${endpoint}`;
return [{ json: { action, runner_url, prompt, task_id, chat_id: chatId, source: 'n8n', executor, received_text: rawText } }];

const response = $json || {};
const result = response.result || {};
const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const status = String(result.status || (response.ok ? 'PASS' : 'UNKNOWN'));
const statusLabel = status === 'PASS' ? "\uc644\ub8cc" : status === 'BLOCKED' ? "\ub9c9\ud798" : status === 'FAIL' ? "\uc2e4\ud328" : status;
const taskId = String(result.task_id || response.task_id || $node['Normalize TAC Command'].json.task_id || 'unknown');
const rawSummary = String(result.summary || response.message || response.error || "\ubcf4\uace0 \ub0b4\uc6a9\uc774 \ube44\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.");
const cleanSummary = rawSummary
  .replace(/^\[[A-Z]+\].*reason=.*$/m, '')
  .replace(/Codex output:/g, "\uc0c1\uc138 \ubcf4\uace0:")
  .trim();
const summary = escapeHtml(cleanSummary.slice(0, 2850));
const text = [
  "[Kindred AI Controller]",
  "\uc0c1\ud0dc: " + statusLabel,
  "\uc791\uc5c5\ubc88\ud638: " + taskId,
  '',
  "\uacb0\uacfc \uc694\uc57d:",
  summary || "\uc791\uc5c5\uc740 \ub05d\ub0ac\uc9c0\ub9cc \uc694\uc57d\uc774 \ube44\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.",
  '',
  "\ud655\uc778 \uc2dc\uac01: " + new Date().toISOString()
].join('\n').slice(0, 3900);
return [{ json: { ok: !!response.ok, status, task_id: taskId, telegram_text: text, chat_id: $node['Normalize TAC Command'].json.chat_id, runner_response: response } }];
